mapper.select:
select FIN_BASE_RULE_INFO.BASE_RULE_ID baseRuleId, FIN_BASE_RULE_INFO.EFF_DATE effDate, FIN_BASE_RULE_INFO.RATE_TYPE rateType, FIN_BASE_RULE_INFO.RATE*100 rate, FIN_BASE_RULE_INFO.COEFFICIENT coefficient, FIN_BASE_RULE_INFO.INDEX_ID indexId, FIN_BASE_RULE_INFO.INDEX_SOURCE indexSource, FIN_BASE_RULE_INFO.SPREAD_RATE*100 spreadRate, FIN_BASE_RULE_INFO.RESET_TYPE resetType, prd_layer_param.PROD_STYLE prodStyle, prd_layer_param.TERM_MAX investmentCycle, FIN_BASE_RULE_INFO.BASE_RULE_TYPE baseRuleType, FIN_BASE_RULE_INFO.PUBLISH_TYPE publishType, FIN_BASE_RULE_INFO.RATE_LOWER*100 rateLower, FIN_BASE_RULE_INFO.RATE_LIMIT*100 rateLimit, FIN_PRODUCT.VDATE vdate, FIN_BASE_RULE_INFO.FINPROD_ID finprodId from FIN_BASE_RULE_INFO, FIN_PRODUCT left join prd_layer_param on FIN_PRODUCT.FINPROD_ID = prd_layer_param.FINPROD_ID where FIN_BASE_RULE_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID and (FIN_BASE_RULE_INFO.FINPROD_ID = #{finprodId,jdbcType=VARCHAR} or prd_layer_param.P_FINPROD_ID = #{finprodId,jdbcType=VARCHAR}) and FIN_BASE_RULE_INFO.BRANCH = 0
AND FIN_BASE_RULE_INFO.BASE_RULE_TYPE = #{baseRuleType,jdbcType=VARCHAR}
AND FIN_BASE_RULE_INFO.PUBLISH_TYPE = #{publishType,jdbcType=VARCHAR}
and FIN_BASE_RULE_INFO.EFF_DATE = to_date(#{effDate},'yyyy-MM-dd')
and (FIN_BASE_RULE_INFO.EFF_DATE = FIN_PRODUCT.VDATE OR FIN_PRODUCT.FINPROD_TYPE2= #{finprodType2, jdbcType=VARCHAR})
